 projects:[['name','Nome','text'],['project_type','Tipo','text'],['description','Descrição','textarea'],['objective','Objetivo','textarea'],['domain','Domínio','domain'],['status','Status','select','idea,active,paused,completed,archived'],['start_date','Data de início','date'],['end_date','Data de encerramento','date'],['project_code','Código do Projeto','text'],['visibility','Visibilidade','visibility']],
