let db={},page='home',editing=null,activeTab='overview',user={id:'demo-user',email:'Demonstração'};
function uid(){return crypto.randomUUID ? crypto.randomUUID() : Date.now()+'-'+Math.random()}
function init(){const saved=localStorage.getItem('memoria-perene'); if(saved) db=JSON.parse(saved); else {Object.entries(seed).forEach(([t,rows])=>db[t]=rows.map(r=>fromSeed(t,r))); db.relations=[];db.files=[];db.record_versions=[];db.citations=[]} Object.keys(fields).forEach(t=>db[t]??=[]);db.inbox_items??=[];db.relations??=[];renderNav();showPage('home')}
function fromSeed(t,r){let o={id:uid(),owner_id:user.id,visibility:'private',created_at:new Date().toISOString(),updated_at:new Date().toISOString(),metadata:{}}; if(t==='entities')Object.assign(o,{canonical_name:r[0],entity_type:r[1],domain:r[2],short_description:r[3],status:'active'});if(t==='knowledge_items')Object.assign(o,{title:r[0],knowledge_type:r[1],domain:r[2],content:r[3],status:r[4],confidence:85,source_mode:'personal'});if(t==='experiences')Object.assign(o,{title:r[0],experience_type:r[1],domain:r[2],rating:r[3],description:r[4],occurred_at:new Date().toISOString()});if(t==='decisions')Object.assign(o,{title:r[0],decision_type:r[1],domain:r[2],context:r[3],status:r[4],decision_date:'2026-08-01'});if(t==='projects')Object.assign(o,{name:r[0],project_type:r[1],domain:r[2],description:r[3],status:r[4]});if(t==='sources')Object.assign(o,{title:r[0],source_type:r[1],domain:r[2],notes:r[3],reliability:80});if(t==='inbox_items')Object.assign(o,{title:r[0],input_type:r[1],domain:r[2],raw_text:r[3],processing_status:r[4],submitted_at:new Date().toISOString()});return o}
function persist(){localStorage.setItem('memoria-perene',JSON.stringify(db))}
function renderNav(){document.querySelector('#nav').innerHTML=navItems.map(([id,ic,name])=>`<button class="nav-link ${page===id?'active':''}" data-nav="${id}"><span>${ic}</span>${name}</button>`).join('');document.querySelectorAll('[data-nav]').forEach(x=>x.onclick=()=>{showPage(x.dataset.nav);closeMobile()})}
function showPage(p){page=p;editing=null;renderNav();document.querySelector('#breadcrumb').textContent=navItems.find(x=>x[0]===p)?.[2]||'Memória Lucenera';let out={home:dashboard,capture:capture,inbox:inbox,search:searchPage,organization:()=>window.memoryOrganizationPage?.()||'<div class="empty">Carregando organização…</div>',reviews:reviews,admin:admin}[p];document.querySelector('#content').innerHTML=out?out():listPage(p);bindPage()}
const recs=t=>db[t].filter(x=>!x.deleted_at); const title=o=>o.title||o.canonical_name||o.name;
function dashboard(){let total=['entities','knowledge_items','experiences','decisions','projects','sources'].reduce((n,t)=>n+recs(t).length,0), pending=recs('inbox_items').filter(x=>x.processing_status!=='approved').length,review=recs('knowledge_items').filter(x=>x.status==='review'||(x.next_review_at&&new Date(x.next_review_at)<new Date())).length;let recent=[...Object.entries(db).filter(([t])=>labels[t]).flatMap(([t,a])=>a.map(x=>({...x,_type:t})))] .sort((a,b)=>new Date(b.created_at)-new Date(a.created_at)).slice(0,5);let domainCounts={};Object.values(db).flat().forEach(x=>{if(x.domain)domainCounts[x.domain]=(domainCounts[x.domain]||0)+1});let top=Object.entries(domainCounts).sort((a,b)=>b[1]-a[1]).slice(0,5);return `<div class="page-heading"><div><h1>Bom dia.</h1><p class="subheading">Sua memória está crescendo — mantenha o que importa ao alcance.</p></div></div><div class="dashboard-actions"><button class="btn primary" data-add="inbox_items">＋ Adicionar memória</button><button class="btn" data-add="knowledge_items">Adicionar conhecimento</button><button class="btn" data-add="experiences">Adicionar experiência</button><button class="btn" data-add="decisions">Registrar decisão</button><button class="btn" data-add="file">Enviar arquivo</button></div><section class="metric-grid"><button class="metric metric-button" data-dashboard-target="search" aria-label="Pesquisar todos os registros"><div class="label">TOTAL DE REGISTROS</div><div class="value">${total}</div><div class="trend">Abrir pesquisa →</div></button><button class="metric metric-button" data-dashboard-target="inbox" aria-label="Abrir itens aguardando revisão"><div class="label">AGUARDANDO REVISÃO</div><div class="value">${pending}</div><div class="trend">Abrir caixa de entrada →</div></button><button class="metric metric-button" data-dashboard-target="reviews" aria-label="Abrir revisões pendentes"><div class="label">REVISÕES PENDENTES</div><div class="value">${review}</div><div class="trend">Revisar agora →</div></button><button class="metric metric-button" data-dashboard-target="projects" aria-label="Abrir projetos ativos"><div class="label">PROJETOS ATIVOS</div><div class="value">${recs('projects').filter(x=>x.status==='active').length}</div><div class="trend">Abrir projetos →</div></button></section><section class="split-grid"><div class="card"><h3>Últimos registros</h3>${recent.map(row).join('')}</div><div class="card"><h3>Domínios mais utilizados</h3><div class="domain-list">${top.map(([d,n])=>`<div class="domain-line"><span>${d}</span><div class="bar"><span style="width:${n/top[0][1]*100}%"></span></div><b>${n}</b></div>`).join('')||'<p class="muted">Sem domínios ainda.</p>'}</div><h3 style="margin-top:28px">Projetos ativos</h3>${recs('projects').filter(x=>x.status==='active').map(row).join('')||'<p class="muted">Nenhum projeto ativo.</p>'}</div></section>`}
function row(x){return `<div class="list-row"><div class="record-icon">${icons[x._type]||'◌'}</div><div class="record-main"><button class="record-link" data-open="${x._type}:${x.id}">${title(x)}</button><small>${labels[x._type]} · ${x.domain||x.status||'Sem domínio'}</small></div>${x.status?`<span class="tag ${x.status==='review'?'review':x.status==='active'?'active':''}">${x.status}</span>`:''}</div>`}
function listPage(t){let records=recs(t);let heading=labels[t]+'s',knowledge=t==='knowledge_items';return `<div class="page-heading"><div><h1>${heading}</h1><p class="subheading">${records.length} ${records.length===1?'registro encontrado':'registros encontrados'}</p></div><button class="btn primary" data-add="${t}">＋ Adicionar ${labels[t].toLowerCase()}</button></div><div class="filters"><input id="listSearch" placeholder="Filtrar por texto"><select id="domainFilter"><option value="">Todas as categorias</option>${domains.map(d=>`<option>${d}</option>`).join('')}</select>${knowledge?'<input id="subcategoryFilter" placeholder="Filtrar por subcategoria">':''}<select id="statusFilter"><option value="">Todos os status</option><option>active</option><option>draft</option><option>review</option><option>approved</option><option>decided</option><option>archived</option></select></div><div class="table-wrap"><table><thead><tr><th>Registro</th><th>Tipo</th><th>Categoria</th>${knowledge?'<th>Subcategoria</th>':''}<th>Status</th><th>Atualizado</th></tr></thead><tbody id="recordRows">${records.map(x=>tableRow(t,x)).join('')||`<tr><td colspan="${knowledge?6:5}" class="empty">Ainda não há registros aqui.</td></tr>`}</tbody></table></div>`}
function tableRow(t,x){return `<tr><td><button class="record-link" data-open="${t}:${x.id}">${title(x)}</button></td><td>${x[`${t.slice(0,-1)}_type`]||x.entity_type||'—'}</td><td>${x.domain||'—'}</td>${t==='knowledge_items'?`<td>${x.subcategory||'—'}</td>`:''}<td>${x.status?`<span class="tag">${x.status}</span>`:'—'}</td><td>${date(x.updated_at)}</td></tr>`}
function capture(){return `<div class="page-heading"><div><h1>Capturar</h1><p class="subheading">Registre algo agora. Você organiza depois.</p></div><button class="btn primary" data-record-voice>🎙 Gravar memória</button></div><div class="voice-hero"><div class="voice-orb">🎙</div><div><h3>Uma memória por voz</h3><p>Grave livremente. A transcrição será preservada e você revisará a memória estruturada antes de salvar.</p></div><button class="btn primary" data-record-voice>Gravar memória</button></div><div class="type-grid"><button class="capture-option" data-capture="note"><b>✎ Escrever</b><small>Uma ideia, observação ou anotação rápida.</small></button><button class="capture-option" data-capture="file"><b>⇧ Enviar arquivo</b><small>PDF, documento, imagem, áudio ou planilha.</small></button><button class="capture-option" data-capture="link"><b>↗ Adicionar link</b><small>Guarde uma página e seu comentário pessoal.</small></button><button class="capture-option" data-capture="audio"><b>◉ Registrar áudio</b><small>Envie uma gravação para sua caixa de entrada.</small></button></div><div class="card" style="margin-top:20px"><h3>Como funciona</h3><p class="muted">Tudo o que for capturado entra na caixa de entrada. A partir dela, você pode transformar o material em conhecimento, entidade, experiência ou decisão.</p></div>`}
function inbox(){let a=recs('inbox_items');return `<div class="page-heading"><div><h1>Caixa de entrada</h1><p class="subheading">Materiais esperando para encontrar seu lugar.</p></div><button class="btn primary" data-add="inbox_items">＋ Nova captura</button></div><div class="filters"><select id="inboxStatus"><option value="">Todos os status</option><option>new</option><option>processing</option><option>awaiting_review</option><option>approved</option><option>failed</option></select><select id="domainFilter"><option value="">Todos os domínios</option>${domains.map(d=>`<option>${d}</option>`).join('')}</select></div><div class="card">${a.map(x=>{let documentButton=x.file_id&&['new','failed','awaiting_review'].includes(x.processing_status)?`<button class="btn primary" data-process-document="${x.id}">${x.metadata?.document_analysis_proposal?'Revisar análise':'Interpretar com IA'}</button>`:'';let bookButton=window.bookActionButton?.(x)||'';return `<div class="list-row"><div class="record-icon">▣</div><div class="record-main"><button class="record-link" data-open="inbox_items:${x.id}">${x.title||'Sem título'}</button><small>${x.input_type} · ${x.domain||'Sem domínio'} · ${date(x.submitted_at)}</small></div><span class="tag ${x.processing_status==='approved'?'active':'review'}">${x.processing_status}</span>${documentButton}${bookButton}<button class="btn secondary" data-organize="${x.id}">Organizar manualmente</button></div>`}).join('')||'<div class="empty">Sua caixa de entrada está vazia.</div>'}</div>`}
function searchPage(){return `<div class="page-heading"><div><h1>Pesquisar</h1><p class="subheading">Encontre ideias, pessoas, decisões e suas conexões.</p></div></div><div class="card"><input id="globalQuery" autofocus placeholder="Pesquise em toda a sua memória..." style="width:100%;font-size:17px;padding:14px"><div class="filters" style="margin-top:14px"><select id="searchType"><option value="">Todos os tipos</option>${Object.entries(labels).map(([v,l])=>`<option value="${v}">${l}</option>`).join('')}</select><select id="searchDomain"><option value="">Todas as categorias</option>${domains.map(d=>`<option>${d}</option>`).join('')}</select><input id="searchSubcategory" placeholder="Subcategoria"><select id="searchReview"><option value="">Qualquer revisão</option><option value="yes">Necessita revisão</option></select></div></div><div id="searchResults" class="card" style="margin-top:16px"><div class="empty">Comece digitando para pesquisar sua base.</div></div>`}
function reviews(){let know=recs('knowledge_items').filter(x=>x.status==='review'||(x.next_review_at&&new Date(x.next_review_at)<=new Date())), dec=recs('decisions').filter(x=>x.review_date&&new Date(x.review_date)<=new Date()&&x.status!=='reviewed'), inboxes=recs('inbox_items').filter(x=>['new','awaiting_review'].includes(x.processing_status));return `<div class="page-heading"><div><h1>Revisões</h1><p class="subheading">O que merece sua atenção agora.</p></div></div><div class="split-grid"><div class="card"><h3>Conhecimentos para revisar <span class="tag review">${know.length}</span></h3>${know.map(x=>row({...x,_type:'knowledge_items'})).join('')||'<p class="muted">Tudo em dia por aqui.</p>'}<h3 style="margin-top:25px">Decisões para avaliar <span class="tag review">${dec.length}</span></h3>${dec.map(x=>row({...x,_type:'decisions'})).join('')||'<p class="muted">Nenhuma decisão vencida.</p>'}</div><div class="card"><h3>Caixa de entrada <span class="tag review">${inboxes.length}</span></h3>${inboxes.map(x=>row({...x,_type:'inbox_items'})).join('')||'<p class="muted">Nada aguardando classificação.</p>'}</div></div>`}
function admin(){return `<div class="page-heading"><div><h1>Administração</h1><p class="subheading">Listas e preferências da sua base.</p></div></div><div class="split-grid"><div class="card"><h3>Domínios</h3>${domains.map(d=>`<div class="list-row"><div class="record-main"><b>${d}</b></div><span class="tag">configurável</span></div>`).join('')}<button class="btn secondary" style="margin-top:14px" id="newDomain">＋ Novo domínio</button></div><div class="card"><h3>Dados e privacidade</h3><p class="muted">Exporte sua base a qualquer momento. Arquivos e registros permanecem privados por padrão.</p><button class="btn secondary" id="exportCsv">Exportar entidades (CSV)</button><button class="btn secondary" id="exportJson" style="margin-left:8px">Exportar tudo (JSON)</button><h3 style="margin-top:28px">Tipos de registro</h3><p class="muted">Entidades, conhecimentos, experiências, decisões, projetos, fontes e relações podem ser ampliados no Supabase.</p><button class="btn secondary" id="logoutBtn">Sair da demonstração</button></div></div>`}
function detail(t,id){let x=(db[t]||[]).find(y=>y.id===id);if(!x)return showPage(t);page='detail';editing={t,id};document.querySelector('#breadcrumb').textContent=labels[t];let related=db.relations.filter(r=>r.source_id===id||r.target_id===id);let text=x.content||x.detailed_description||x.description||x.context||x.notes||x.raw_text||'Sem descrição detalhada.';let bookButton=t==='inbox_items'?(window.bookActionButton?.(x)||''):'';let classification=x.subcategory?`${x.domain||'Sem categoria'} › ${x.subcategory}`:(x.domain||'Sem categoria');document.querySelector('#content').innerHTML=`<div class="detail-hero"><span class="tag">${labels[t]}</span><h1>${title(x)}</h1><p class="subheading">${classification} · atualizado ${date(x.updated_at)}</p><div class="form-actions" style="margin:14px 0 0"><button class="btn secondary" data-edit="${t}:${id}">Editar</button><button class="btn primary" data-relation="${t}:${id}">Criar relação</button>${bookButton}</div></div><div class="tabs"><button class="tab ${activeTab==='overview'?'active':''}" data-tab="overview">Visão geral</button><button class="tab ${activeTab==='relations'?'active':''}" data-tab="relations">Relações (${related.length})</button>${['knowledge_items','decisions','experiences'].includes(t)?`<button class="tab ${activeTab==='history'?'active':''}" data-tab="history">Histórico</button>`:''}</div><div class="detail-content" id="detailContent">${activeTab==='overview'?`<p>${escapeHtml(text).replace(/\n/g,'<br>')}</p><div class="card" style="margin-top:20px"><h3>Informações</h3><p><b>Categoria:</b> ${x.domain||'—'}<br><b>Subcategoria:</b> ${x.subcategory||'—'}<br><b>Código do Projeto:</b> ${x.project_code||'—'}<br><b>Status:</b> ${x.status||'ativo'}<br><b>Visibilidade:</b> ${x.visibility||'private'}<br><b>Criado em:</b> ${date(x.created_at)}</p></div>`:activeTab==='relations'?relationsView(related,id):historyView(t,id)}</div>`;bindPage()}
function relationsView(items,id){return `<h3>Conexões deste registro</h3>${items.length?items.map(r=>{let other=r.source_id===id?r.target_id:r.source_id,ot=r.source_id===id?r.target_type:r.source_type,rx=(db[ot]||[]).find(x=>x.id===other);return `<div class="relation"><small>${r.source_id===id?'Relação de saída':'Relação de entrada'} · ${r.relation_type}</small><br><button class="record-link" data-open="${ot}:${other}">${title(rx||{title:'Registro relacionado'})}</button>${r.description?`<br><small>${r.description}</small>`:''}</div>`}).join(''):'<p class="muted">Nenhuma relação criada ainda.</p>'}<button class="btn secondary" data-relation="${editing.t}:${id}" style="margin-top:12px">＋ Criar relação</button>`}
function historyView(t,id){let a=db.record_versions.filter(x=>x.record_type===t&&x.record_id===id);return `<h3>Histórico de versões</h3>${a.length?a.map(x=>`<div class="relation"><b>Versão ${x.version_number}</b><br><small>${date(x.changed_at)} · ${x.change_reason||'Alteração registrada'}</small></div>`).join(''):'<p class="muted">A primeira alteração deste registro aparecerá aqui.</p>'}`}
function fieldHtml(f,x={}){x=x||{};let [k,l,type,opts]=f;let val=x[k]??(k==='visibility'?'private':k==='status'?(opts||'').split(',')[0]:'');let control;if(type==='textarea')control=`<textarea name="${k}">${val}</textarea>`;else if(type==='select'||type==='domain'||type==='visibility'){let values=type==='domain'?domains:type==='visibility'?['private','shared','company','public']:opts.split(',');control=`<select name="${k}">${values.map(v=>`<option ${v===val?'selected':''}>${v}</option>`).join('')}</select>`}else if(type==='boolean')control=`<select name="${k}"><option value="">Não informado</option><option value="true" ${val===true||val==='true'?'selected':''}>Sim</option><option value="false" ${val===false||val==='false'?'selected':''}>Não</option></select>`;else control=`<input name="${k}" type="${type}" value="${String(val).replace(/"/g,'&quot;')}">`;return `<label class="${type==='textarea'?'full-span':''}">${l}${control}</label>`}
function openForm(t,x=null){if(t==='file')return fileForm();if(t==='inbox_items')return inboxForm();let fs=fields[t];modal(`${x?'Editar':'Adicionar'} ${labels[t]}`,`<form id="recordForm"><div class="form-grid">${fs.map(f=>fieldHtml(f,x)).join('')}</div><div class="form-actions"><button type="button" class="btn secondary" data-close>Cancelar</button><button class="btn primary">${x?'Salvar alterações':'Criar registro'}</button></div></form>`);document.querySelector('#recordForm').onsubmit=e=>{e.preventDefault();let data=Object.fromEntries(new FormData(e.target));Object.keys(data).forEach(k=>{if(data[k]==='')data[k]=null;if(['confidence','rating','reliability'].includes(k)&&data[k]!=null)data[k]=Number(data[k]);if(['would_repeat','would_recommend'].includes(k)&&data[k]!=null)data[k]=data[k]==='true'});save(t,data,x);closeModal()}}
function inboxForm(kind='note'){modal('Nova captura',`<form id="inboxForm"><div class="form-grid"><label class="full-span">Título<input name="title" required placeholder="Dê um nome para capturar agora"></label><label>Tipo<select name="input_type">${['note','text','conversation','pdf','image','audio','email','url','spreadsheet'].map(v=>`<option ${v===kind?'selected':''}>${v}</option>`).join('')}</select></label><label>Domínio<select name="domain"><option value="">Sem domínio</option>${domains.map(d=>`<option>${d}</option>`).join('')}</select></label><label>Código do Projeto<input name="project_code" placeholder="Ex.: 26.181"></label><label class="full-span">Texto, comentário ou URL<textarea name="raw_text" placeholder="Escreva livremente ou cole um link"></textarea></label><label>Visibilidade<select name="visibility"><option>private</option><option>shared</option></select></label></div><div class="form-actions"><button type="button" class="btn secondary" data-close>Cancelar</button><button class="btn primary">Enviar à caixa de entrada</button></div></form>`);document.querySelector('#inboxForm').onsubmit=e=>{e.preventDefault();let a=Object.fromEntries(new FormData(e.target));save('inbox_items',{...a,processing_status:'new',submitted_at:new Date().toISOString()});closeModal();showPage('inbox')}}
function fileForm(){modal('Enviar arquivo',`<form id="fileForm"><div class="form-grid"><label class="full-span">Arquivo<input type="file" name="file" accept=".pdf,.docx,.txt,.jpg,.jpeg,.png,.webp,.mp3,.wav,.xlsx,.csv" required></label><label class="full-span">Comentário opcional<textarea name="note" placeholder="O que este arquivo contém?"></textarea></label><label>Domínio<select name="domain"><option value="">Sem domínio</option>${domains.map(d=>`<option>${d}</option>`).join('')}</select></label></div><p class="muted">Tipos aceitos: PDF, DOCX, TXT, imagem, áudio e planilha. Em Supabase, o arquivo será enviado ao bucket privado <b>${activeStorageBucket}</b>.</p><div class="form-actions"><button type="button" class="btn secondary" data-close>Cancelar</button><button class="btn primary">Enviar arquivo</button></div></form>`);document.querySelector('#fileForm').onsubmit=e=>{e.preventDefault();let f=e.target.file.files[0], note=e.target.note.value,domain=e.target.domain.value;if(!f)return;let file={id:uid(),owner_id:user.id,original_filename:f.name,mime_type:f.type,file_size:f.size,storage_path:'local/'+f.name,processing_status:'uploaded',visibility:'private',created_at:new Date().toISOString()};db.files.push(file);save('inbox_items',{title:f.name,input_type:'file',raw_text:note,file_id:file.id,domain,processing_status:'new',submitted_at:new Date().toISOString()});persist();closeModal();toast('Arquivo enviado para a caixa de entrada');showPage('inbox')}}
function relationForm(t,id){modal('Criar relação',`<form id="relationForm"><div class="form-grid"><label>Tipo do destino<select name="target_type" id="relationType">${Object.entries(labels).filter(([k])=>k!=='inbox_items').map(([v,l])=>`<option value="${v}">${l}</option>`).join('')}</select></label><label>Registro de destino<select name="target_id" id="relationTarget"></select></label><label>Tipo de relação<select name="relation_type">${['related_to','located_in','created_by','designed_by','written_by','visited_during','part_of','influences','supports','contradicts','analyzes','recommends','mentions','applies_to','source_for','decision_about','experience_with'].map(x=>`<option>${x}</option>`).join('')}</select></label><label>Confiança<input name="confidence" type="number" min="0" max="100" value="80"></label><label class="full-span">Descrição opcional<textarea name="description"></textarea></label></div><div class="form-actions"><button type="button" class="btn secondary" data-close>Cancelar</button><button class="btn primary">Criar relação</button></div></form>`);let update=()=>{let typ=document.querySelector('#relationType').value;document.querySelector('#relationTarget').innerHTML=recs(typ).filter(x=>x.id!==id).map(x=>`<option value="${x.id}">${title(x)}</option>`).join('')||'<option value="">Nenhum registro disponível</option>'};document.querySelector('#relationType').onchange=update;update();document.querySelector('#relationForm').onsubmit=e=>{e.preventDefault();let a=Object.fromEntries(new FormData(e.target));if(!a.target_id)return toast('Selecione outro registro');db.relations.push({id:uid(),owner_id:user.id,source_type:t,source_id:id,...a,confidence:Number(a.confidence),created_at:new Date().toISOString(),updated_at:new Date().toISOString()});persist();closeModal();toast('Relação criada');detail(t,id)}}
function save(t,data,old=null){let now=new Date().toISOString();if(old){if(['knowledge_items','decisions','experiences'].includes(t))db.record_versions.push({id:uid(),owner_id:user.id,record_type:t,record_id:old.id,version_number:db.record_versions.filter(v=>v.record_id===old.id).length+1,snapshot:{...old},change_reason:'Edição manual',changed_at:now,changed_by:user.id});Object.assign(old,data,{updated_at:now})}else{let x={id:uid(),owner_id:user.id,visibility:'private',created_at:now,updated_at:now,metadata:{},...data};db[t].push(x)}persist();toast(old?'Alterações salvas':'Registro criado')}
function organize(id){let x=db.inbox_items.find(a=>a.id===id);modal('Organizar material',`<p class="muted">Transforme “${x.title}” em um registro estruturado.</p><div class="type-grid">${['entities','knowledge_items','experiences','decisions'].map(t=>`<button class="capture-option" data-transform="${t}"><b>${icons[t]} ${labels[t]}</b><small>Criar a partir deste material.</small></button>`).join('')}</div>`);document.querySelectorAll('[data-transform]').forEach(b=>b.onclick=()=>{let t=b.dataset.transform;closeModal();openForm(t,{title:x.title,canonical_name:x.title,content:x.raw_text,description:x.raw_text,context:x.raw_text,domain:x.domain});x.processing_status='approved';persist()})}
function bindPage(){document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>openForm(b.dataset.add));document.querySelectorAll('[data-dashboard-target]').forEach(b=>b.onclick=()=>showPage(b.dataset.dashboardTarget));document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>{let [t,id]=b.dataset.open.split(':');activeTab='overview';detail(t,id)});document.querySelectorAll('[data-capture]').forEach(b=>b.onclick=()=>b.dataset.capture==='file'||b.dataset.capture==='audio'?fileForm():inboxForm(b.dataset.capture==='link'?'url':'note'));document.querySelectorAll('[data-organize]').forEach(b=>b.onclick=()=>organize(b.dataset.organize));document.querySelectorAll('[data-process-document]').forEach(b=>b.onclick=()=>window.processDocument?.(b.dataset.processDocument));document.querySelectorAll('[data-edit]').forEach(b=>{let[t,id]=b.dataset.edit.split(':');b.onclick=()=>openForm(t,db[t].find(x=>x.id===id))});document.querySelectorAll('[data-relation]').forEach(b=>{let[t,id]=b.dataset.relation.split(':');b.onclick=()=>relationForm(t,id)});document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{activeTab=b.dataset.tab;detail(editing.t,editing.id)});let ls=document.querySelector('#listSearch');if(ls)ls.oninput=filterList;document.querySelector('#domainFilter')?.addEventListener('change',filterList);document.querySelector('#subcategoryFilter')?.addEventListener('input',filterList);document.querySelector('#statusFilter')?.addEventListener('change',filterList);document.querySelector('#globalQuery')?.addEventListener('input',runSearch);document.querySelector('#searchType')?.addEventListener('change',runSearch);document.querySelector('#searchDomain')?.addEventListener('change',runSearch);document.querySelector('#searchSubcategory')?.addEventListener('input',runSearch);document.querySelector('#searchReview')?.addEventListener('change',runSearch);document.querySelector('#exportCsv')?.addEventListener('click',exportCsv);document.querySelector('#exportJson')?.addEventListener('click',()=>download('memoria-perene-completa.json',JSON.stringify(db,null,2),'application/json'));document.querySelector('#logoutBtn')?.addEventListener('click',logout);document.querySelector('#newDomain')?.addEventListener('click',()=>toast('Novos domínios podem ser incluídos na tabela domains do Supabase.'));window.bindBookIngestion?.();if(page==='search')runSearch()}
function filterList(){let q=(document.querySelector('#listSearch')?.value||'').toLowerCase(),d=document.querySelector('#domainFilter')?.value||'',sub=(document.querySelector('#subcategoryFilter')?.value||'').toLowerCase(),s=document.querySelector('#statusFilter')?.value||'';let a=recs(page).filter(x=>(!q||JSON.stringify(x).toLowerCase().includes(q))&&(!d||x.domain===d)&&(!sub||String(x.subcategory||'').toLowerCase().includes(sub))&&(!s||x.status===s));document.querySelector('#recordRows').innerHTML=a.map(x=>tableRow(page,x)).join('')||`<tr><td colspan="${page==='knowledge_items'?6:5}" class="empty">Nenhum registro encontrado.</td></tr>`;document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>{let[t,id]=b.dataset.open.split(':');detail(t,id)})}
function runSearch(){let q=(document.querySelector('#globalQuery').value||'').toLowerCase(),t=document.querySelector('#searchType').value,d=document.querySelector('#searchDomain').value,sub=(document.querySelector('#searchSubcategory').value||'').toLowerCase(),rev=document.querySelector('#searchReview').value;let a=Object.entries(labels).flatMap(([type])=>(db[type]||[]).filter(x=>!x.deleted_at&&(!t||type===t)&&(!d||x.domain===d)&&(!sub||String(x.subcategory||'').toLowerCase().includes(sub))&&(!rev||(x.status==='review'||x.next_review_at))&&(!q||JSON.stringify(x).toLowerCase().includes(q))).map(x=>({...x,_type:type})));document.querySelector('#searchResults').innerHTML=a.length?`<h3>${a.length} resultado(s)</h3>${a.map(row).join('')}`:'<div class="empty">Nenhum resultado encontrado.</div>';document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>{let[z,id]=b.dataset.open.split(':');detail(z,id)})}
function modal(title,body,size=''){document.querySelector('#modalRoot').innerHTML=`<div class="modal-backdrop"><div class="modal ${size==='wide'?'modal-wide':''}"><div class="modal-head"><h2>${title}</h2><button class="icon" data-close>×</button></div><div class="modal-body">${body}</div></div></div>`;document.querySelectorAll('[data-close]').forEach(b=>b.onclick=closeModal)}function closeModal(){document.querySelector('#modalRoot').innerHTML=''}function toast(msg){let x=document.querySelector('#toast');x.textContent=msg;x.classList.add('show-toast');setTimeout(()=>x.classList.remove('show-toast'),2600)}function date(v){return v?new Intl.DateTimeFormat('pt-BR',{dateStyle:'medium'}).format(new Date(v)):'—'}function escapeHtml(s){return String(s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]))}function download(name,data,type){let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type}));a.download=name;a.click();URL.revokeObjectURL(a.href);toast('Exportação iniciada')}function exportCsv(){let a=recs('entities'),cols=['canonical_name','entity_type','domain','short_description','visibility'];download('entidades.csv',[cols.join(';'),...a.map(x=>cols.map(k=>`"${String(x[k]||'').replace(/"/g,'""')}"`).join(';'))].join('\n'),'text/csv')}function closeMobile(){document.querySelector('#sidebar').classList.remove('open')}function logout(){localStorage.removeItem('memoria-perene');document.querySelector('#appView').classList.add('hidden');document.querySelector('#authView').classList.remove('hidden')}
function enterApp(account){user={id:account?.id||'demo-user',email:account?.email||'Demonstração'};document.querySelector('#userName').textContent=user.email;document.querySelector('#userMode').textContent=account?'Conta Supabase':'Demonstração';document.querySelector('#authView').classList.add('hidden');document.querySelector('#appView').classList.remove('hidden');init()}
document.querySelector('#demoBtn').onclick=()=>enterApp(null);document.querySelector('#authForm').onsubmit=async e=>{e.preventDefault();if(!sb){document.querySelector('#authMessage').textContent='Configure as credenciais do Supabase em app.js ou use a demonstração.';return}let email=document.querySelector('#email').value,password=document.querySelector('#password').value;let {data,error}=await sb.auth.signInWithPassword({email,password});if(error)document.querySelector('#authMessage').textContent=error.message;else enterApp(data.user)};document.querySelector('#signUpBtn').onclick=async()=>{if(!sb){document.querySelector('#authMessage').textContent='Configure as credenciais do Supabase antes de criar uma conta.';return}let email=document.querySelector('#email').value,password=document.querySelector('#password').value;if(!email||!password){document.querySelector('#authMessage').textContent='Informe e-mail e senha antes de criar a conta.';return}let {data,error}=await sb.auth.signUp({email,password,options:{emailRedirectTo:window.location.href}});if(error)document.querySelector('#authMessage').textContent=error.message;else if(data.session)enterApp(data.user);else document.querySelector('#authMessage').textContent='Conta criada. Confira seu e-mail para confirmar o acesso.'};document.querySelector('#quickAdd').onclick=()=>openForm('inbox_items');document.querySelector('#globalSearch').onclick=()=>showPage('search');document.querySelector('#openNav').onclick=()=>document.querySelector('#sidebar').classList.add('open');document.querySelector('#closeNav').onclick=closeMobile;document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();showPage('search')}});

// Memória por voz: a IA roda somente na Edge Function; o navegador nunca recebe segredo algum.
let voiceRecorder,voiceStream,voiceChunks=[],voiceClock,voiceSeconds=0;
document.addEventListener('click',e=>{const button=e.target.closest('[data-record-voice]');if(button)openVoiceRecorder()});
async function openVoiceRecorder(){
  if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){toast('A gravação por voz não é suportada neste navegador.');return}
  try{voiceStream=await navigator.mediaDevices.getUserMedia({audio:true});voiceChunks=[];voiceSeconds=0;voiceRecorder=new MediaRecorder(voiceStream);voiceRecorder.ondataavailable=e=>{if(e.data.size)voiceChunks.push(e.data)};voiceRecorder.onstop=()=>{voiceStream.getTracks().forEach(t=>t.stop());clearInterval(voiceClock);const audio=new Blob(voiceChunks,{type:voiceRecorder.mimeType||'audio/webm'});processVoiceAudio(audio)};modal('Gravando memória',`<div class="recording"><div class="record-indicator">●</div><div class="recording-status">GRAVANDO</div><div id="voiceTimer" class="recording-time">00:00</div><p class="muted">Fale livremente. A transcrição original será preservada.</p><button id="finishVoice" class="btn primary">Finalizar gravação</button></div>`);voiceRecorder.start();voiceClock=setInterval(()=>{voiceSeconds++;const t=document.querySelector('#voiceTimer');if(t)t.textContent=String(Math.floor(voiceSeconds/60)).padStart(2,'0')+':'+String(voiceSeconds%60).padStart(2,'0')},1000);document.querySelector('#finishVoice').onclick=()=>{document.querySelector('#finishVoice').disabled=true;document.querySelector('#finishVoice').textContent='Preparando áudio…';voiceRecorder.stop()}
  }catch(err){toast('Não foi possível acessar o microfone. Verifique a permissão do navegador.')}
}
async function processVoiceAudio(audio){
  closeModal();modal('Interpretando memória',`<div class="recording"><div class="record-indicator">…</div><h3>Transcrevendo e organizando</h3><p class="muted">A transcrição e a sugestão de estrutura estão sendo preparadas.</p></div>`);
  try{if(!sb)throw new Error('Conecte o Supabase para transcrever por voz.');const {data:{session}}=await sb.auth.getSession();if(!session)throw new Error('Entre na sua conta para usar a gravação por voz.');const form=new FormData();form.append('audio',audio,'memoria.webm');const response=await fetch(`${activeSupabaseUrl}/functions/v1/interpret-memory`,{method:'POST',headers:{Authorization:`Bearer ${session.access_token}`,apikey:activeSupabaseKey},body:form});const result=await response.json();if(!response.ok)throw new Error(result.error||'Não foi possível processar o áudio.');closeModal();openVoiceReview(result)
  }catch(err){closeModal();toast(err.message||'Falha ao processar o áudio.')}
}
function openVoiceReview(result){const s=result.structured||{};const projectOptions=recs('projects').map(p=>`<option value="${p.id}">${title(p)}</option>`).join('');modal('Revisar memória por voz',`<form id="voiceReview"><div class="form-grid"><label class="full-span">Título sugerido<input name="title" value="${escapeHtml(s.title||'Memória por voz')}"></label><label class="full-span">Resumo<textarea name="summary">${escapeHtml(s.summary||'')}</textarea></label><label>Área / domínio<select name="domain"><option value="">Sem domínio</option>${domains.map(d=>`<option ${d===s.domain?'selected':''}>${d}</option>`).join('')}</select></label><label>Projeto<select name="project_id"><option value="">Sem projeto</option>${projectOptions}</select></label><label>Categoria<select name="knowledge_type">${['anotação','insight','opinião','análise','tese','decisão','experiência','conceito'].map(x=>`<option ${x===s.knowledge_type?'selected':''}>${x}</option>`).join('')}</select></label><label>Data<input name="memory_date" type="date" value="${s.memory_date||''}"></label><label class="full-span">Pessoas citadas<input name="people" value="${escapeHtml((s.people||[]).join(', '))}"></label><label class="full-span">Lugares<input name="places" value="${escapeHtml((s.places||[]).join(', '))}"></label><label class="full-span">Tags<input name="tags" value="${escapeHtml((s.tags||[]).join(', '))}"></label><label class="full-span">Próximas ações<textarea name="next_actions">${escapeHtml((s.next_actions||[]).join('\n'))}</textarea></label><label class="full-span">Conteúdo estruturado<textarea name="content">${escapeHtml(s.content||result.transcript||'')}</textarea></label><label class="full-span">Transcrição original (preservada)<textarea readonly>${escapeHtml(result.transcript||'')}</textarea></label></div><div class="form-actions"><button type="button" class="btn secondary" data-close>Cancelar</button><button class="btn primary">Confirmar e salvar</button></div></form>`);document.querySelector('#voiceReview').onsubmit=e=>{e.preventDefault();const a=Object.fromEntries(new FormData(e.target));const metadata={people:splitList(a.people),places:splitList(a.places),tags:splitList(a.tags),next_actions:splitLines(a.next_actions),memory_date:a.memory_date||null,capture_mode:'voice'};save('inbox_items',{input_type:'audio',title:a.title,raw_text:result.transcript,original_transcription:result.transcript,source_channel:'voice',processing_status:'approved',visibility:'private',submitted_at:new Date().toISOString(),metadata});const memory={title:a.title,summary:a.summary,content:a.content,knowledge_type:a.knowledge_type,domain:a.domain||null,status:'draft',confidence:70,source_mode:'personal',visibility:'private',metadata};save('knowledge_items',memory);const saved=recs('knowledge_items').slice(-1)[0];if(a.project_id&&saved){db.relations.push({id:uid(),owner_id:user.id,source_type:'knowledge_items',source_id:saved.id,relation_type:'part_of',target_type:'projects',target_id:a.project_id,description:'Memória por voz vinculada durante a revisão.',confidence:100,created_at:new Date().toISOString(),updated_at:new Date().toISOString()});persist()}closeModal();toast('Memória salva e transcrição original preservada.');detail('knowledge_items',saved.id)}}
function splitList(v){return String(v||'').split(',').map(x=>x.trim()).filter(Boolean)}function splitLines(v){return String(v||'').split('\n').map(x=>x.trim()).filter(Boolean)}

// A confirmação da revisão grava no Supabase como usuário autenticado (RLS), além do espelho local da interface.
async function saveVoiceMemoryToSupabase(form, transcript, metadata){
  const { data:{session} }=await sb.auth.getSession();
  if(!session)throw new Error('Sua sessão expirou. Entre novamente e tente salvar.');
  const owner_id=session.user.id;
  const {data:inbox,error:inboxError}=await sb.from('inbox_items').insert({owner_id,input_type:'audio',title:form.title,raw_text:transcript,original_transcription:transcript,source_channel:'voice',processing_status:'approved',visibility:'private',project_code:form.project_code||null,submitted_at:new Date().toISOString(),metadata}).select().single();
  if(inboxError)throw inboxError;
  const {data:knowledge,error:knowledgeError}=await sb.from('knowledge_items').insert({owner_id,title:form.title,summary:form.summary,content:form.content,knowledge_type:form.knowledge_type,domain:form.domain||null,status:'draft',confidence:70,source_mode:'personal',visibility:'private',project_code:form.project_code||null,metadata}).select().single();
  if(knowledgeError)throw knowledgeError;
  if(form.project_id){const {error:relationError}=await sb.from('relations').insert({owner_id,source_type:'knowledge_items',source_id:knowledge.id,relation_type:'part_of',target_type:'projects',target_id:form.project_id,description:'Memória por voz vinculada durante a revisão.',confidence:100});if(relationError)throw relationError}
  return {inbox,knowledge};
}
function openVoiceReview(result){const s=result.structured||{};const projectOptions=recs('projects').map(p=>`<option value="${p.id}">${title(p)}</option>`).join('');modal('Revisar memória por voz',`<form id="voiceReview"><div class="form-grid"><label class="full-span">Título sugerido<input name="title" value="${escapeHtml(s.title||'Memória por voz')}"></label><label class="full-span">Resumo<textarea name="summary">${escapeHtml(s.summary||'')}</textarea></label><label>Área / domínio<select name="domain"><option value="">Sem domínio</option>${domains.map(d=>`<option ${d===s.domain?'selected':''}>${d}</option>`).join('')}</select></label><label>Projeto<select name="project_id"><option value="">Sem projeto</option>${projectOptions}</select></label><label>Categoria<select name="knowledge_type">${['anotação','insight','opinião','análise','tese','decisão','experiência','conceito'].map(x=>`<option ${x===s.knowledge_type?'selected':''}>${x}</option>`).join('')}</select></label><label>Data<input name="memory_date" type="date" value="${s.memory_date||''}"></label><label class="full-span">Pessoas citadas<input name="people" value="${escapeHtml((s.people||[]).join(', '))}"></label><label class="full-span">Lugares<input name="places" value="${escapeHtml((s.places||[]).join(', '))}"></label><label class="full-span">Tags<input name="tags" value="${escapeHtml((s.tags||[]).join(', '))}"></label><label class="full-span">Próximas ações<textarea name="next_actions">${escapeHtml((s.next_actions||[]).join('\n'))}</textarea></label><label class="full-span">Conteúdo estruturado<textarea name="content">${escapeHtml(s.content||result.transcript||'')}</textarea></label><label class="full-span">Transcrição original (preservada)<textarea readonly>${escapeHtml(result.transcript||'')}</textarea></label><label>Código do Projeto<input name="project_code" placeholder="Ex.: 26.181"></label></div><div class="form-actions"><button type="button" class="btn secondary" data-close>Cancelar</button><button class="btn primary" id="saveVoiceReview">Confirmar e salvar</button></div></form>`);document.querySelector('#voiceReview').onsubmit=async e=>{e.preventDefault();const a=Object.fromEntries(new FormData(e.target));const metadata={people:splitList(a.people),places:splitList(a.places),tags:splitList(a.tags),next_actions:splitLines(a.next_actions),memory_date:a.memory_date||null,capture_mode:'voice'};const button=document.querySelector('#saveVoiceReview');button.disabled=true;button.textContent='Salvando…';try{const saved=await saveVoiceMemoryToSupabase(a,result.transcript,metadata);db.inbox_items.push(saved.inbox);db.knowledge_items.push(saved.knowledge);if(a.project_id)db.relations.push({id:uid(),owner_id:user.id,source_type:'knowledge_items',source_id:saved.knowledge.id,relation_type:'part_of',target_type:'projects',target_id:a.project_id,description:'Memória por voz vinculada durante a revisão.',confidence:100,created_at:new Date().toISOString(),updated_at:new Date().toISOString()});persist();closeModal();toast('Memória salva no Supabase.');detail('knowledge_items',saved.knowledge.id)}catch(error){button.disabled=false;button.textContent='Confirmar e salvar';toast(error.message||'Não foi possível salvar a memória.')}}}

const PASSWORD_RECOVERY_REDIRECT = memoriaConfig.passwordRecoveryRedirect || (window.location.protocol.startsWith('http') ? `${window.location.origin}/` : '');

function openPasswordRecoveryForm(){
  modal('Criar nova senha', `<form id="passwordRecoveryForm"><p class="muted">Escolha uma nova senha para sua conta da Memória Lucenera.</p><div class="form-grid"><label class="full-span">Nova senha<input name="password" type="password" minlength="6" autocomplete="new-password" required></label><label class="full-span">Confirmar nova senha<input name="confirmation" type="password" minlength="6" autocomplete="new-password" required></label></div><p id="passwordRecoveryMessage" class="form-message"></p><div class="form-actions"><button class="btn primary" id="confirmNewPassword">Salvar nova senha</button></div></form>`);
  document.querySelector('#passwordRecoveryForm').onsubmit=async event=>{
    event.preventDefault();
    const values=Object.fromEntries(new FormData(event.target));
    const message=document.querySelector('#passwordRecoveryMessage');
    if(values.password!==values.confirmation){message.textContent='As duas senhas precisam ser iguais.';return}
    const button=document.querySelector('#confirmNewPassword');button.disabled=true;button.textContent='Salvando…';
    const {error}=await sb.auth.updateUser({password:values.password});
    if(error){button.disabled=false;button.textContent='Salvar nova senha';message.textContent=error.message;return}
    await sb.auth.signOut();closeModal();document.querySelector('#appView').classList.add('hidden');document.querySelector('#authView').classList.remove('hidden');document.querySelector('#password').value='';document.querySelector('#authMessage').textContent='Senha atualizada. Entre agora com sua nova senha.';
  };
}

document.querySelector('#forgotPasswordBtn').onclick=async()=>{
  const email=document.querySelector('#email').value.trim();
  const message=document.querySelector('#authMessage');
  if(!email){message.textContent='Digite primeiro o e-mail da sua conta.';document.querySelector('#email').focus();return}
  const button=document.querySelector('#forgotPasswordBtn');button.disabled=true;button.textContent='Enviando…';
  const {error}=await sb.auth.resetPasswordForEmail(email,{redirectTo:PASSWORD_RECOVERY_REDIRECT});
  button.disabled=false;button.textContent='Esqueci minha senha';
  message.textContent=error?error.message:'Enviamos um link de recuperação. Verifique sua caixa de entrada e também o spam.';
};

if(sb)sb.auth.onAuthStateChange(event=>{if(event==='PASSWORD_RECOVERY')setTimeout(openPasswordRecoveryForm,0)});
